 "content": "def transform(grid):
    """Combine four 4x4 color panels by taking the highest-priority color per cell."""
    rank = {0: 0, 5: 1, 8: 2, 4: 3, 9: 4}
    starts = (0, 5, 10, 15)
    panels = [
        [[grid[r][start + c] for c in range(4)] for r in range(4)]
        for start in starts
    ]
    return [
        [max((panel[r][c] for panel in panels), key=lambda color: rank.get(color, 0))
         for c in range(4)]
        for r in range(4)
    ]
